    adcs_vec3_t cross;
    double dot;
    double cross_norm;
    double angle;

    if (angle_rad != NULL)
        *angle_rad = 0.0;

    if ((a == NULL) || (b == NULL) || (angle_rad == NULL))
        return ADCS_E_NULL;

    if ((!adcs_is_finite_vec3(a)) || (!adcs_is_finite_vec3(b)))
        return ADCS_E_DEGENERATE;

    if ((adcs_vec3_norm(a) <= ADCS_EPS_NORM) || (adcs_vec3_norm(b) <= ADCS_EPS_NORM))
        return ADCS_E_DEGENERATE;

    cross = adcs_vec3_cross(a, b);
    dot = adcs_vec3_dot(a, b);
    cross_norm = adcs_vec3_norm(&cross);

    angle = atan2(cross_norm, dot);
    *angle_rad = ADCS_CLAMP(angle, 0.0, ADCS_PI);

    return ADCS_OK;
}

